using System.Buffers.Binary;
using System.Globalization;

namespace Tedd.Tdfs;

/// <summary>
/// Identifies an immutable stored object (128-bit, random, generated by the uploader). The same id always means the
/// same bytes. String form is exactly 32 lowercase hexadecimal characters.
/// </summary>
/// <param name="Value">The 128-bit value.</param>
public readonly record struct ObjectId(UInt128 Value) : IComparable<ObjectId>, IComparable
{
    /// <summary>Orders ids by their 128-bit value (the order of inventories, plans and reports).</summary>
    public int CompareTo(ObjectId other) => Value.CompareTo(other.Value);

    /// <inheritdoc />
    public int CompareTo(object? obj) => obj switch
    {
        null => 1,
        ObjectId other => CompareTo(other),
        _ => throw new ArgumentException("The object is not an ObjectId.", nameof(obj)),
    };

    /// <summary>Less-than by value.</summary>
    public static bool operator <(ObjectId left, ObjectId right) => left.Value < right.Value;

    /// <summary>Greater-than by value.</summary>
    public static bool operator >(ObjectId left, ObjectId right) => left.Value > right.Value;

    /// <summary>Less-than-or-equal by value.</summary>
    public static bool operator <=(ObjectId left, ObjectId right) => left.Value <= right.Value;

    /// <summary>Greater-than-or-equal by value.</summary>
    public static bool operator >=(ObjectId left, ObjectId right) => left.Value >= right.Value;

    /// <summary>Number of characters in the string form.</summary>
    public const int StringLength = 32;

    /// <summary>Number of bytes in the binary form.</summary>
    public const int ByteLength = 16;

    /// <summary>Creates a new random, non-zero object id from the supplied random source.</summary>
    public static ObjectId New(IRandomSource r)
    {
        ArgumentNullException.ThrowIfNull(r);
        Span<byte> buffer = stackalloc byte[ByteLength];
        UInt128 value;
        do
        {
            r.Fill(buffer);
            value = BinaryPrimitives.ReadUInt128LittleEndian(buffer);
        }
        while (value == UInt128.Zero);

        return new ObjectId(value);
    }

    /// <summary>True for the reserved all-zero id.</summary>
    public bool IsEmpty => Value == UInt128.Zero;

    /// <summary>Parses exactly 32 hexadecimal characters (canonical form is lowercase; uppercase is accepted).</summary>
    /// <exception cref="FormatException">The string is not 32 hexadecimal characters.</exception>
    public static ObjectId Parse(string s)
    {
        ArgumentNullException.ThrowIfNull(s);
        return TryParse(s, out var id) ? id : throw new FormatException("Invalid object id; expected exactly 32 hexadecimal characters.");
    }

    /// <summary>Tries to parse exactly 32 hexadecimal characters.</summary>
    public static bool TryParse(string? s, out ObjectId id) => TryParse(s.AsSpan(), out id);

    /// <summary>Tries to parse exactly 32 hexadecimal characters.</summary>
    public static bool TryParse(ReadOnlySpan<char> s, out ObjectId id)
    {
        id = default;
        if (s.Length != StringLength || !IdentifierFormat.IsHex(s))
            return false;
        if (!UInt128.TryParse(s, NumberStyles.AllowHexSpecifier, CultureInfo.InvariantCulture, out var value))
            return false;
        id = new ObjectId(value);
        return true;
    }

    /// <summary>Writes the 16-byte little-endian binary form.</summary>
    public void WriteBytes(Span<byte> destination)
    {
        if (destination.Length < ByteLength)
            throw new ArgumentException("Destination must be at least 16 bytes.", nameof(destination));
        BinaryPrimitives.WriteUInt128LittleEndian(destination, Value);
    }

    /// <summary>Reads the 16-byte little-endian binary form.</summary>
    public static ObjectId FromBytes(ReadOnlySpan<byte> source)
    {
        if (source.Length < ByteLength)
            throw new ArgumentException("Source must be at least 16 bytes.", nameof(source));
        return new ObjectId(BinaryPrimitives.ReadUInt128LittleEndian(source));
    }

    /// <summary>Returns exactly 32 lowercase hexadecimal characters.</summary>
    public override string ToString() => Value.ToString("x32", CultureInfo.InvariantCulture);
}
